-- 📚 꼭집 주거 사전 — SH 목록 「모집중」은 접수 중이라는 뜻이 아니다 · SH · 대조 기간 전체
-- 재계산 SQL(관리 API에서 그대로 실행 · 읽기만). 범위: source_page_checks SH 원문 키마다 오류 없는 대조 전부 · 대조일(KST)에 카드 접수 끝이 이미 지났는데 목록 「모집중」인 대조.
-- 확인 2026-10-29 · 실행 0.3초 미만(2초 상한 · 관리 API 응답 시간 − 같은 시각 select 1 왕복) · 결과:
-- {"keys": 12, "checks": 186, "모집중_checks": 170, "모집중_keys": 11, "모집중_but_ended_keys": 3, "모집중_but_ended_ex": [{"card": "SH_310041", "card_end": "2026-10-08", "checked": "2026-10-09"}, {"card": "SH_310650", "card_end": "2026-10-15", "checked": "2026-10-16"}, {"card": "SH_310653", "card_end": "2026-10-15", "checked": "2026-10-16"}], "모집중_no_end_keys": 4, "statuses": {"(빈 값)": 16, "모집중": 170}, "first": "2026-10-08", "last": "2026-10-29"}
with c as(select source_key,card_id,(checked_at at time zone 'Asia/Seoul')::date d,page_status,coalesce(card_apply_end_confirmed,card_apply_end) e from source_page_checks where source='SH' and error is null)select json_build_object('keys',(select count(distinct source_key) from c),'checks',(select count(*) from c),'모집중_checks',(select count(*) from c where page_status='모집중'),'모집중_keys',(select count(distinct source_key) from c where page_status='모집중'),'모집중_but_ended_keys',(select count(distinct source_key) from c where page_status='모집중' and e < d),'모집중_but_ended_ex',(select json_agg(o) from(select distinct on(card_id) json_build_object('card',card_id,'card_end',e,'checked',d) o from c where page_status='모집중' and e < d order by card_id,d desc)q),'모집중_no_end_keys',(select count(distinct source_key) from c where page_status='모집중' and e is null),'statuses',(select json_object_agg(coalesce(nullif(page_status,''),'(빈 값)'),n) from(select page_status,count(*)n from c group by 1)q),'first',(select min(d) from c),'last',(select max(d) from c))j;
